import type { UltrasoundOrganId, UltrasoundSpecies } from './ultrasoundReferenceData';

export type UltrasoundDifferentialExplanation = {
  name: string;
  matches: string[];
  organs?: UltrasoundOrganId[];
  species?: UltrasoundSpecies[];
  pathophysiology: string;
  appearance: string;
  clinical: string;
};
type Entry = [name: string, matches: string[], pathophysiology: string, appearance: string, clinical: string, organs?: UltrasoundOrganId[]];
const entries = (rows: Entry[]): UltrasoundDifferentialExplanation[] => rows.map(([name, matches, pathophysiology, appearance, clinical, organs]) => ({ name, matches, pathophysiology, appearance, clinical, organs }));

/** Educational synthesis: organ chapters in BSAVA, Thrall and Point-of-Care Ultrasound.
 * Matching only the differential paragraph keeps a diagnosis mentioned as a caveat
 * from becoming a suggested differential. No probability is inferred by matching.
 */
export const ULTRASOUND_DIFFERENTIAL_EXPLANATIONS = entries([
  ['Comunicação interatrial / forame oval patente', ['comunicacao interatrial', 'forame oval'], 'Comunicação entre átrios permite desvio conforme pressão e complacência. Volume desviado pode dilatar câmaras direitas; elevação de pressão direita pode inverter o fluxo e permitir mistura com sangue sistêmico.', 'Fluxo transseptal no Doppler confirma uma comunicação que o modo B pode não delimitar. Dropout por orientação do feixe pode simular um buraco sem defeito anatômico.', 'Relacionar fluxo, câmaras e oxigenação, com avaliação de múltiplas janelas. Tamanho aparente isolado não define repercussão.', ['heart']],
  ['Comunicação interventricular', ['comunicacao interventricular', 'defeito do septo ventricular'], 'Defeito pequeno oferece resistência e mantém gradiente, produzindo jato rápido. Defeito amplo permite equalização; resistência pulmonar e sistêmica determinam direção e volume desviado.', 'Jato atravessando o septo, com remodelamento conforme o volume. Velocidade baixa pode ocorrer em grande defeito com pressões semelhantes, e não significar lesão discreta.', 'Relacionar anatomia, direção, valva aórtica e pressão pulmonar. A avaliação cardiológica diferencia defeito isolado de malformação complexa.', ['heart']],
  ['Persistência do ducto arterioso', ['ducto arterioso'], 'Uma conexão fetal entre aorta e artéria pulmonar não fecha. O gradiente pós-natal usual favorece fluxo para os pulmões e sobrecarga esquerda; hipertensão pulmonar importante pode reduzir ou inverter o desvio.', 'Fluxo contínuo/turbulento próximo à artéria pulmonar e dilatação esquerda podem ocorrer. No desvio invertido, o padrão clássico pode faltar.', 'Confirmar direção e hemodinâmica antes de considerar fechamento. Relacionar oxigenação, pressões e remodelamento.', ['heart']],
  ['Estenose subaórtica / aórtica', ['estenose subaortica', 'estenose aortica', 'estenose subaórtica/aórtica'], 'Obstrução fixa por tecido fibroso ou malformação da valva aumenta a pressão necessária à ejeção e promove hipertrofia. O nível subvalvar deve ser separado da obstrução dinâmica por SAM.', 'Crista/estreitamento, fluxo acelerado/turbulento e possível dilatação pós-estenótica. Lesão pequena pode não ser visível no modo B apesar de alterações de fluxo.', 'Relacionar anatomia e Doppler alinhado, idade, raça, carga e arritmias; o gradiente não deve ser interpretado sem contexto.', ['heart']],
  ['Estenose pulmonar', ['estenose pulmonar'], 'Fusão valvar, displasia/hipoplasia de anel ou estreitamento em outro nível aumenta resistência à ejeção direita. Hipertrofia é resposta à pressão, sem proporcionalidade perfeita com gravidade.', 'Valva alterada e Doppler acelerado, com hipertrofia direita e dilatação pós-estenótica variável. A anatomia pode incluir anomalias coronárias importantes para procedimentos.', 'Definir nível, gradiente, anel e malformações associadas com cardiologia; a espessura ventricular isolada não classifica a estenose.', ['heart']],
  ['Displasia atrioventricular / anomalia de Ebstein', ['displasia mitral', 'tricuspide', 'ebstein'], 'Ligação e desenvolvimento anormais de folhetos, cordas e músculos papilares prejudicam coaptação. Regurgitação impõe sobrecarga de volume às câmaras correspondentes.', 'Folhetos/cordas anormais, regurgitação e aumento atrial/ventricular variável. Deslocamento apical relevante da tricúspide pode indicar Ebstein, mas há diferença normal de posição entre valvas.', 'Separar malformação de degeneração, endocardite e regurgitação secundária. Relacionar idade, raça e repercussão hemodinâmica.', ['heart']],
  ['Cor triatriatum / malformações complexas', ['cor triatriatum', 'tetralogia', 'canal atrioventricular', 'truncus'], 'Membrana intra-atrial pode dificultar enchimento; defeitos combinados de septos, valvas e grandes vasos alteram mistura e distribuição do sangue. O efeito depende das conexões e resistências, não de um nome isolado.', 'Membrana, comunicações e origem/posição anormal de vasos podem aparecer. Doppler e múltiplas janelas determinam fluxo e gradiente.', 'Mapear o conjunto em avaliação especializada, relacionando cianose, congestão e hematócrito. Uma imagem parcial pode subestimar a complexidade.', ['heart']],
  ['Comunicação arterioportal', ['arterioportal'], 'Uma conexão entre artéria e circulação portal transmite pressão/pulsação arterial ao sistema venoso. Isso pode produzir hipertensão portal e abertura de colaterais, reduzindo o fluxo efetivo pelo fígado.', 'Vasos dilatados e tortuosos e fluxo portal pulsátil ou hepatofugal em segmentos afetados. Doppler espectral e rastreamento do trajeto são necessários para interpretar a comunicação.', 'Distinguir de shunt portossistêmico e trombose. Relacionar ascite, função hepática e mapeamento vascular especializado.', ['liver']],
  ['Mineralização adrenal incidental / degenerativa', ['variacao incidental', 'degenerativa'], 'Depósitos minerais podem surgir em tecido degenerado sem secreção hormonal anormal, especialmente em gatos. Uma lesão nodular também pode mineralizar; o depósito não informa o tipo celular.', 'Focos hiperecogênicos, às vezes com sombra. Confirmar que pertencem à glândula e avaliar tecido adjacente, tamanho e contorno.', 'Relacionar espécie e demais achados; não concluir tumor funcional pela presença de mineral.', ['adrenals']],
  ['Hipoadrenocorticismo / atrofia adrenal', ['hipoadrenocorticismo', 'atrofia por supressao'], 'Destruição cortical primária pode reduzir tecido produtor de corticosteroides. Supressão por glicocorticoides ou redução do estímulo trófico também pode diminuir volume, por mecanismos diferentes.', 'Glândulas pequenas podem apoiar a suspeita, mas há sobreposição com variação anatômica e limitação técnica. Uma adrenal não vista não equivale a uma adrenal atrofiada.', 'Usar história de medicamentos, sinais, eletrólitos e teste hormonal apropriado. Tamanho não confirma nem exclui insuficiência adrenal.', ['adrenals']],
  ['Estrutura embrionária ocular persistente / corpo estranho', ['estruturas vitreas', 'corpo estranho'], 'Remanescentes embrionários podem formar bandas que ligam estruturas oculares e, em alguns casos, manter vasos. Objeto traumático cria uma interface física adicional e pode provocar inflamação.', 'Bandas ou focos brilhantes; Doppler pode detectar vascularização residual, e alguns objetos geram sombra. Trajeto e inserção ajudam a distinguir de retina descolada.', 'Relacionar idade, trauma e exame oftálmico. Em suspeita de ferida aberta, evitar pressão e priorizar avaliação especializada.', ['eyes']],
  ['Hiperplasia mucinosa / pólipo biliar', ['hiperplasia mucinosa', 'polipo'], 'Proliferação mucosa e dilatação das glândulas formam projeções e pequenas cavidades; retenção de muco pode acompanhar alterações da drenagem. Neoplasia pode gerar projeções parecidas.', 'Tecido fixo ligado à parede e pequenos cistos murais, diferente de sedimento que muda de posição.', 'Avaliar evolução, base, fluxo e efeito sobre a via biliar. A forma polipoide não fornece diagnóstico histológico.', ['gallbladder']],
  ['Divertículo uracal / úraco persistente', ['uracal', 'uraco'], 'Persistência do canal embrionário pode criar bolsa no ápice vesical ou comunicação com umbigo. Retenção de urina favorece inflamação e infecção recorrente.', 'Projeção no ápice, cavidade ou trajeto líquido; pregas da bexiga vazia podem confundir a leitura.', 'Relacionar idade, descarga umbilical e infecções; confirmar comunicação e distensão antes de classificar a lesão.', ['bladder']],
  ['Fibroplasia eosinofílica esclerosante gastrointestinal felina', ['fibroplasia eosinofilica', 'fgesf', 'fibroplasia', 'esclerosante'], 'Infiltração eosinofílica com fibroblastos reativos e colágeno denso produz uma massa fibrosa/inflamatória. A parede perde a arquitetura e pode afetar linfonodos.', 'Massa escura transmural e perda de camadas, frequentemente em junções gastrointestinais; não há aspecto exclusivo que a separe de tumor.', 'No gato com massa, considerar junto a linfoma/carcinoma. Histopatologia e investigação de fatores associados definem a interpretação.', ['stomach','small-intestine','colon']],
  ['Pneumatoses / gás intramural', ['pneumatose', 'gas mural', 'enterocolite necrosante'], 'Lesão da mucosa, pressão, isquemia ou produção microbiana permite gás no interstício. O mecanismo varia e não representa necessariamente necrose irreversível.', 'Ecos intensos e reverberação dentro da parede; confirmar posição em vários planos e separar do gás luminal.', 'Relacionar perfusão, dor, integridade, procedimentos e sinais sistêmicos. Instabilidade ou suspeita de isquemia altera a urgência.', ['stomach','small-intestine','colon']],
  ['Cisto de duplicação intestinal', ['duplicacao intestinal'], 'Tecido intestinal duplicado forma cavidade com revestimento e músculo próprios. Pode comprimir a alça ou causar obstrução, independentemente de infecção.', 'Centro líquido e parede em íntima relação com o intestino, às vezes com interfaces em camadas.', 'Confirmar anatomia e comunicação; diferenciar de cisto mesentérico/coleção. A classificação pode exigir confirmação cirúrgica e histológica.', ['small-intestine']],
  ['Remanescente ovariano', ['remanescente ovariano', 'tecido ovariano ectopico'], 'Tecido ovariano residual responde às gonadotrofinas e pode produzir hormônios e ciclos, mesmo após castração. Pequena quantidade de tecido pode ser funcional.', 'Folículos ou tecido luteal podem aparecer junto ao pedículo conforme a fase; fora de atividade, o tecido pode não ser detectável.', 'Relacionar cio, citologia/hormônios e cirurgia. Exame negativo não exclui remanescente e estrutura próxima não confirma ovário.', ['ovaries']],
  ['Bócio por deficiência de iodo / alteração de síntese', ['deficiencia de iodo', 'alteracao de sintese', 'bocio'], 'Menor síntese hormonal pode elevar estímulo trófico e causar hiperplasia glandular. Assim, crescimento pode coexistir com função insuficiente, ao contrário de proliferação autônoma hipersecretora.', 'Aumento difuso bilateral, com ecogenicidade variável e possíveis cistos; não se diferencia função apenas pela imagem.', 'Rever dieta, medicamentos e testes tireoidianos no contexto da espécie. Não deduzir hiperfunção por tamanho.', ['thyroid']],
  ['Atrofia / hipoplasia / degeneração testicular', ['atrofia', 'degeneracao', 'hipoplasia', 'maturacao'], 'Desenvolvimento incompleto ou perda de epitélio germinativo reduz massa tubular. Lesões térmicas, inflamatórias, hormonais ou medicamentosas podem evoluir para atrofia e fibrose.', 'Volume menor, mediastino relativamente evidente e textura variável. Testículo pré-púbere tem padrão de maturação próprio.', 'Relacionar idade, posição, história e avaliação seminal. A imagem não mede fertilidade nem distingue todas as causas de perda tubular.', ['testes']],
  ['Epididimite / granuloma espermático', ['epididimite', 'granuloma espermatico'], 'Inflamação e obstrução dilatam ductos e provocam edema. Extravasamento de espermatozoides pode gerar reação granulomatosa, enquanto infecção pode produzir abscesso.', 'Epidídimo aumentado/heterogêneo, com fluxo aumentado ou coleção. Confirmar localização fora do parênquima testicular.', 'Relacionar dor, reprodução e investigação de infecção, incluindo brucelose quando pertinente. Aspecto não identifica o agente.', ['testes']],
  ['Variação por baixa distensão / artefato de plano', ['baixa distensao', 'variacao fisiologica'], 'Quando o lúmen contrai, a mesma parede ocupa menor superfície e parece mais espessa. Corte oblíquo prolonga a espessura aparente sem aumento de tecido.', 'Pregas e espessamento relativamente uniforme que variam com distensão e plano; avaliação repetida ajuda a separar pseudolesão de alteração persistente.', 'Registrar enchimento e técnica. Interpretar a medida junto à distribuição e aos exames clínicos, sem atribuir cistite a uma bexiga vazia.', ['bladder']],
  ['Estenose / ureterite / hiperplasia mucosa', ['estenose', 'ureterite', 'hiperplasia mucosa', 'polipo fibroepitelial'], 'Inflamação, cicatrização ou proliferação estreita o lúmen; pressão se transmite ao ureter e à pelve a montante. Lesão benigna pode obstruir tanto quanto um tumor.', 'Parede focalmente espessa ou projeção intraluminal, com dilatação proximal; pode não haver cálculo ou sombra.', 'Localizar transição, avaliar ambos os rins e relacionar função/diurese e procedimentos prévios. Histologia pode ser necessária para distinguir hiperplasia, pólipo e tumor.', ['ureters']],
  ['Glaucoma / atrofia ocular', ['glaucoma cronico', 'atrofia ocular'], 'Pressão intraocular persistente pode distender o globo; inflamação ou trauma grave pode causar perda de tecido e retração. Tamanho também varia com conformação.', 'Globo aumentado ou reduzido, com alterações de câmaras, lente e parede. A medida não informa pressão atual nem capacidade visual.', 'Relacionar tonometria, exame oftálmico e visão. Usar cortes equivalentes, sem compressão do globo.', ['eyes']],
  ['Fibrose e cirrose', ['fibrose', 'cirrose', 'remodelamento cronico'], 'A agressão persistente ativa reparação e deposição de matriz extracelular. A fibrose remodela o órgão; na cirrose há distorção difusa da arquitetura e regeneração nodular, com possível aumento da resistência ao fluxo portal.', 'Interfaces entre tecido preservado, septos e nódulos mudam a dispersão dos ecos, causando textura grosseira ou heterogênea. Retração pode produzir fígado pequeno e irregular; hipertensão portal pode acompanhar ascite e colaterais. Brilho e granulação não são uma medida direta da quantidade de colágeno.', 'Investigar história de hepatopatia, função de síntese, coagulação e circulação portal. Exames e amostragem quando indicada distinguem fibrose de outras causas de padrão semelhante.', ['liver']],
  ['Lipidose hepática', ['lipidose'], 'Acúmulo de lipídios nos hepatócitos aumenta seu volume e altera a composição do parênquima. No gato, anorexia prolongada e doença de base são contextos importantes; gordura na imagem não identifica a causa da anorexia.', 'O aumento das interfaces associado à gordura pode elevar os ecos e a atenuação: fígado brilhante, aumentado e com vasos menos delimitados em profundidade. A intensidade depende da distribuição, técnica e doenças concomitantes.', 'Relacionar ingestão alimentar, perda de peso, icterícia e alterações laboratoriais. Não equiparar fígado brilhante a lipidose confirmada; considerar amostragem e investigar a doença precipitante.', ['liver']],
  ['Hepatopatia vacuolar / esteroidal', ['vacuolar', 'esteroidal'], 'Distensão dos hepatócitos por vacúolos, frequentemente contendo glicogênio no cão exposto a corticosteroides ou estímulo hormonal, aumenta o volume hepático. Não é um diagnóstico etiológico único.', 'Mudanças de composição e interfaces podem produzir hepatomegalia e hiperecogenicidade difusa, com ou sem heterogeneidade e nódulos concomitantes. O ultrassom não mostra a composição de cada vacúolo.', 'Rever uso de corticosteroides, sinais endócrinos, bioquímica e doenças concomitantes. A imagem não confirma hiperadrenocorticismo nem separa vacuolização de lipidose.', ['liver']],
  ['Hepatite e colangio-hepatite', ['hepatite', 'colangio-hepatite', 'colangiohepatite', 'colangite'], 'Inflamação pode envolver hepatócitos, interstício e/ou vias biliares. Edema agudo e infiltração celular podem evoluir para necrose e reparação fibrosa; por isso fases diferentes produzem padrões diferentes.', 'Pode haver fígado escuro e paredes portais relativamente destacadas, padrão misto ou exame aparentemente normal. Na doença crônica, fibrose e regeneração podem alterar textura e contorno. Alterações biliares devem ser descritas separadamente.', 'Relacionar enzimas, bilirrubina, febre, função hepática e achados biliares. O aspecto não identifica agente, tipo de inflamação ou necessidade de antimicrobiano.', ['liver', 'gallbladder']],
  ['Congestão venosa', ['congestao', 'insuficiencia cardiaca direita', 'congestiva'], 'Pressão elevada a jusante dificulta a drenagem venosa. Sangue retido distende vasos e sinusoides; líquido pode extravasar para o interstício e cavidades.', 'Hepatomegalia com veias hepáticas/cava dilatadas, baço aumentado ou parede vesicular edemaciada podem coexistir. O componente líquido pode reduzir ecos, mas a ecogenicidade é variável.', 'Ver coração, pericárdio, cava, volume administrado e sinais de congestão. Distensão venosa e edema precisam ser interpretados com respiração e estado circulatório.', ['liver', 'gallbladder', 'spleen']],
  ['Amiloidose', ['amiloidose', 'amiloid'], 'Proteína amiloide é depositada extracelularmente e modifica a arquitetura. O comprometimento funcional depende do órgão e da distribuição; o depósito não tem uma assinatura acústica exclusiva.', 'Fígado ou rins podem aumentar, ficar heterogêneos ou manter aparência normal. Interfaces entre depósitos e tecido preservado podem mudar os ecos; ausência de alteração não exclui doença.', 'Relacionar raça, doença inflamatória, proteinúria e disfunção do órgão. Confirmar por investigação específica; não diagnosticar depósito amiloide apenas por brilho.', ['liver', 'kidneys']],
  ['Desvio portossistêmico', ['desvio portossistemico', 'shunt', 'desvios portossistemicos'], 'Parte do sangue portal alcança a circulação sistêmica sem passar pelos sinusoides. Menor aporte de fatores tróficos pode reduzir o fígado; alterações congênitas e colaterais adquiridas têm mecanismos e implicações distintos.', 'Fígado pequeno, vaso anômalo e alterações do fluxo portal podem aparecer. Colaterais adquiridas tendem a formar vários vasos tortuosos no contexto de hipertensão portal; o Doppler ajuda a seguir conexões.', 'Relacionar idade, sinais neurológicos episódicos, urólitos e testes de função. Um fígado pequeno não confirma shunt, e ausência de vaso visível não o exclui; pode ser necessária angiografia por TC.', ['liver']],
  ['Hiperplasia nodular / regeneração', ['hiperplasia nodular', 'alteracoes regenerativas', 'nodulos regenerativos'], 'Proliferação não necessariamente neoplásica forma áreas de composição e organização distintas. Pode acompanhar envelhecimento ou reparação após agressão, conforme o órgão.', 'Nódulos podem ser claros, escuros ou mistos e, por vezes, em alvo. O contraste depende de células, gordura, sangue e estroma; não existe aparência que garanta benignidade.', 'Relacionar idade, crescimento, multiplicidade, arquitetura global e resultados de amostragem quando indicada. Achado incidental não deve ser convertido automaticamente em metástase.', ['liver', 'spleen', 'pancreas']],
  ['Linfoma', ['linfoma', 'linfossarcoma'], 'Células linfoides neoplásicas infiltram de modo difuso ou formam massas. A infiltração pode expandir tecido preservando parcialmente a arquitetura ou substituí-la de forma extensa.', 'Pode produzir organomegalia, nódulos escuros, padrão reticular, espessamento intestinal ou massas. No gato, alterações de muscular intestinal e faixa subcapsular renal podem levantar suspeita, mas também têm causas não neoplásicas.', 'Avaliar distribuição, outros órgãos/linfonodos, hemograma e sinais sistêmicos. Inflamação pode se parecer com linfoma; definição e classificação requerem investigação celular/tecidual apropriada.'],
  ['Mastocitoma / infiltração mastocitária', ['mastocit', 'mastocitose'], 'Proliferação de mastócitos pode infiltrar órgãos ou formar lesões focais. Infiltração pequena ou uniforme pode não criar contraste suficiente para ser vista.', 'Baço ou fígado podem apresentar nódulos, aumento ou textura variável, e intestino pode perder camadas. Exame normal não exclui infiltração.', 'Relacionar doença cutânea/visceral e estadiamento. Não concluir presença ou ausência de mastocitose pela aparência do fígado/baço.'],
  ['Neoplasia primária ou metastática', ['neoplas', 'tumor', 'metastase', 'metastatica', 'metastases', 'carcinoma'], 'Proliferação tumoral pode deslocar ou substituir tecido, induzir vasos e produzir necrose/hemorragia. Lesões expansivas e infiltrativas têm efeitos distintos, e tumores diferentes podem produzir a mesma combinação estrutural.', 'Massa sólida, heterogênea, cavitária, em alvo ou infiltrativa pode ocorrer. Invasão de estruturas e alterações regionais ajudam a avaliar extensão, mas textura, tamanho e Doppler não identificam sozinhos histologia ou atividade hormonal.', 'Relacionar idade, sítio primário, distribuição, evolução e repercussão. Planejar estadiamento e confirmação adequada; evitar concluir malignidade somente por heterogeneidade.'],
  ['Hemangioma / hemangiossarcoma', ['hemangioma', 'hemangiossarcoma'], 'Tumores vasculares podem formar canais sanguíneos frágeis, hemorragia e necrose. Sangue acumulado também pode ocorrer em hematoma não tumoral.', 'Massas com áreas claras, escuras e cavidades podem aparecer no baço, fígado ou região cardíaca. O sangue muda de aspecto com coagulação/organização; benignidade e malignidade se sobrepõem.', 'Ver anemia, líquido livre, estabilidade e disseminação. A imagem não separa de modo confiável hemangiossarcoma de hematoma/hemangioma.'],
  ['Hematoma / hemorragia', ['hematoma', 'hemorragia', 'sangue', 'hemorragico', 'hemorragicas'], 'Sangue se acumula por trauma, ruptura vascular, coagulopatia ou sangramento de uma lesão. Conforme coagula e se organiza, seu conteúdo e interfaces mudam.', 'Pode ser anecoico, ecogênico, heterogêneo ou cavitário; coágulo organizado imita massa. Não há equivalência entre sangue recente e líquido necessariamente brilhante.', 'Rever trauma/procedimentos, coagulação, hemograma e estabilidade. Determinar a origem e considerar tumor associado; a ecogenicidade não data com precisão o sangramento.'],
  ['Abscesso / infecção focal', ['abscesso', 'abscess', 'cisto infectado', 'cisto infect'], 'Supuração e necrose formam coleção delimitada. Células, proteínas, tecido desvitalizado e eventualmente gás variam dentro da cavidade.', 'Parede espessa/irregular, debris, septos, gordura reativa e reforço posterior podem ocorrer; gás provoca reverberação/sombra. Pus homogêneo também pode parecer pouco ecogênico.', 'Relacionar febre, dor, inflamação sistêmica e origem. Conteúdo escuro não prova esterilidade; confirmar composição/agente quando indicado e planejar abordagem segura.'],
  ['Granuloma / inflamação granulomatosa', ['granuloma', 'granulomat', 'piogranuloma'], 'Inflamação organizada reúne macrófagos e outros componentes ao redor de agente persistente ou corpo estranho; pode haver fibrose, necrose e mineralização.', 'Massas ou nódulos sólidos/complexos podem ter ecos mistos, cavidades e mineral com sombra. A infiltração transmural intestinal pode simular câncer.', 'Pesquisar exposição, infecção sistêmica, corpo estranho e território de drenagem. A confirmação frequentemente depende de amostragem e testes dirigidos.'],
  ['Cisto simples', ['cisto', 'cistos'], 'Uma cavidade delimitada contém líquido, muitas vezes retido por obstrução ou alteração do desenvolvimento. Cisto verdadeiro possui revestimento, que não é demonstrado histologicamente pelo ultrassom.', 'Centro anecoico, parede fina e reforço posterior favorecem líquido simples. Septos, componentes sólidos e conteúdo complexo ampliam diferenciais; nem toda cavidade é cisto benigno.', 'Relacionar localização, número e evolução. Não extrapolar o termo “cístico” para benignidade ou ausência de infecção.'],
  ['Infarto / isquemia / tromboembolismo', ['infarto', 'isquemia', 'tromboembol', 'embolismo'], 'Interrupção da perfusão lesiona o tecido no território vascular. Edema e necrose predominam inicialmente; organização e cicatriz modificam o aspecto com o tempo.', 'Área em cunha/geográfica ou focal pode começar escura, sem perfusão detectável, e tornar-se brilhante/retraída. Alteração de fluxo precisa ser confirmada com técnica Doppler adequada.', 'Relacionar dor, risco trombótico e outros territórios afetados. Ausência de cor pode ser técnica; padrão e evolução ajudam, sem substituir investigação da causa.'],
  ['Torção', ['torcao'], 'Rotação de um órgão ou pedículo comprime primeiro a drenagem venosa e pode comprometer o influxo arterial. Congestão, edema, hemorragia e necrose podem seguir.', 'Aumento, redução dos ecos, arquitetura heterogênea e pouca/nenhuma perfusão podem ocorrer, conforme fase. A mudança depende do órgão e da duração.', 'Dor aguda e deterioração tornam o conjunto urgente. Confirmar contexto e técnica sem usar ausência isolada de Doppler como diagnóstico.'],
  ['Trombose / obstrução vascular', ['trombose', 'trombo', 'obstrucao/invasao da cava'], 'Material coagulado ocupa parcialmente ou totalmente a luz vascular; pode coexistir com invasão tumoral ou compressão externa.', 'Defeito de enchimento no Doppler e conteúdo ecogênico intraluminal sugerem obstrução, mas trombos recentes podem ser pouco visíveis. Fluxo residual/turbulento pode persistir.', 'Correlacionar hipercoagulabilidade, doença de base e extensão. Diferenciar trombo de invasão pode exigir exame especializado; fluxo ausente também depende dos ajustes.'],
  ['Lama / estase biliar', ['sedimento incidental', 'estase biliar', 'bile espessa', 'lama', 'sedimento'], 'Partículas, pigmentos e mucina podem se acumular com esvaziamento reduzido. A sedimentação depende da consistência e gravidade; material espesso pode se organizar.', 'Lama costuma formar ecos dependentes e móveis, sem sombra mineral típica; bolas de lama podem imitar massa. Organização não dependente exige diferenciar mucocele.', 'Relacionar mobilidade, parede, ductos e perfil hepatobiliar; sedimento isolado não confirma infecção nem obstrução.', ['gallbladder']],
  ['Mucocele biliar', ['mucocele'], 'Acúmulo e organização de mucina/bile espessa impedem esvaziamento. A distensão e lesão da parede podem evoluir para necrose, obstrução e ruptura.', 'Padrão organizado não móvel, estrelado ou em “kiwi”, com combinação de áreas ecogênicas e faixas escuras. Diferenciar de lama que sedimenta; parede e tecidos adjacentes definem suspeita de complicação.', 'Correlacionar dor, icterícia, febre, vias biliares e líquido livre. A urgência depende da repercussão e dos sinais de complicação.', ['gallbladder']],
  ['Colecistite / colangite', ['colecistite', 'colangite', 'colangio'], 'Inflamação da parede vesicular ou ductos produz edema e infiltração; cronicidade pode deixar espessamento fibroso. Agente e esterilidade não são definidos pela imagem.', 'Parede espessada, camadas/halo, sedimento e reação adjacente podem ocorrer. O mesmo halo também aparece no edema por causas sistêmicas.', 'Relacionar febre, dor, bilirrubina e doença concomitante; investigar infecção quando indicada, sem atribuir todo espessamento a causa bacteriana.', ['gallbladder']],
  ['Edema por hipoalbuminemia / pressão venosa / permeabilidade', ['hipoalbum', 'hipoprotein', 'edema', 'anafilaxia', 'sepse', 'sobrecarga hidrica'], 'Menor pressão oncótica, maior pressão hidrostática ou aumento da permeabilidade favorecem extravasamento de líquido. Podem coexistir e atingir várias estruturas.', 'Líquido separa camadas e reduz ecos: halo vesicular, espessamento de parede intestinal, septos pancreáticos escuros e efusões são possíveis. A imagem local não distingue o mecanismo sistêmico.', 'Relacionar albumina, circulação, infusão de fluidos, reação aguda e sinais de sepse. Procurar distribuição multiorgânica e interpretar com o estado hemodinâmico.'],
  ['Cálculo / urolitíase / colelitíase', ['calculo', 'calculi', 'colelit', 'urolit', 'ureterolit', 'nefrolit', 'pancreaticolit'], 'Precipitação/agregação de material forma uma estrutura sólida. Quando impede a drenagem, pressão aumenta a montante, distendendo ductos ou sistema urinário.', 'Foco brilhante e possível sombra posterior; pequenas pedras podem não sombrear. Mobilidade, localização e dilatação a montante ajudam a avaliar importância.', 'Identificar se é obstrutivo, relacionar função do órgão e exames complementares. O brilho/sombra não revela composição mineral nem comprova obstrução.'],
  ['Ruptura / vazamento / peritonite', ['ruptura', 'vazamento', 'peritonite', 'uroabdome', 'perfuracao'], 'Perda de integridade permite extravasamento de urina, bile ou conteúdo digestivo. Irritação química e possível contaminação causam resposta inflamatória e efusão.', 'Líquido, gordura reativa e eventualmente gás livre podem aparecer; o defeito pode não ser visível. A imagem não identifica com segurança qual fluido extravasou.', 'Correlacionar trauma, obstrução, cirurgia, dor e estabilidade. Investigar rapidamente suspeita clínica e analisar o líquido/exame complementar conforme indicação.'],
  ['Hiperplasia mucosa / pólipo', ['polipo', 'hiperplasia mucosa', 'hiperplasia endometrial'], 'Proliferação localizada da mucosa pode formar projeções ou áreas espessadas. Retenção glandular e inflamação podem coexistir.', 'Tecido aderido à parede, às vezes vascularizado, projeta-se para o lúmen; glândulas dilatadas podem parecer pequenas cavidades. Material móvel ou coágulo pode imitar lesão.', 'Ver base de implantação, localização e evolução. Aparência polipoide não comprova benignidade; confirmação depende do contexto e de investigação apropriada.'],
  ['Hiperplasia reativa / hematopoiese extramedular', ['hiperplasia reativa', 'hematopoiese', 'alteracoes reativas', 'linfonodo reativo', 'linfadenite'], 'Estímulo imune expande tecido linfoide; aumento da produção de células sanguíneas fora da medula pode expandir baço. Distribuição focal ou difusa altera o órgão de formas diferentes.', 'Aumento homogêneo ou heterogêneo, nódulos e alterações de forma podem ocorrer. O padrão pode se sobrepor ao de neoplasia.', 'Relacionar hemograma, hemólise, inflamação e território drenado. Um linfonodo ou baço reativo não é reconhecido com certeza apenas pelo tamanho.', ['spleen', 'lymph-nodes']],
  ['Mielolipoma / gordura focal', ['mielolipoma', 'gordura invaginada', 'invaginacao de gordura', 'myelolip'], 'Tecido adiposo, por vezes associado a elementos hematopoiéticos, cria uma região de composição diferente. Gordura no hilo pode ser anatômica, sem representar massa verdadeira.', 'Gordura e suas interfaces podem produzir foco bastante brilhante, às vezes com sombra; localização e continuidade ajudam a interpretar.', 'Confirmar origem e relacionar crescimento/efeito de massa. Brilho intenso não garante que a lesão seja apenas gordura.', ['spleen', 'adrenals']],
  ['Doença renal crônica / displasia / hipoplasia', ['doenca renal cronica', 'displasia', 'hipoplasia', 'nefropatia cronica'], 'Perda de néfrons e reparação fibrosa podem reduzir e deformar o rim. Na displasia, o tecido se desenvolveu de forma desorganizada; na hipoplasia, há menor quantidade de tecido desde o desenvolvimento.', 'Rins pequenos/irregulares, menor contraste corticomedular, mineral e cistos podem aparecer. A imagem não quantifica néfrons funcionais; doenças congênitas e adquiridas se sobrepõem.', 'Relacionar idade, trajetória da função renal, urina, pressão e história familiar. Um rim de aparência normal não exclui doença renal.', ['kidneys']],
  ['Lesão renal aguda / toxicidade', ['lesao aguda', 'doenca renal aguda', 'lesao renal aguda', 'nefrotoxic', 'toxicidade', 'etilenoglicol'], 'Lesão tubular, edema e depósitos podem surgir após insulto tóxico, isquêmico ou infeccioso. A composição muda antes ou sem uma alteração morfológica detectável.', 'Rins podem aumentar ou ficar brilhantes, mas também parecer normais. Depósitos relacionados a certas toxinas podem criar banda medular/mineral, sem exclusividade.', 'Relacionar exposição, débito urinário, eletrólitos e evolução laboratorial. A ausência de sinais ultrassonográficos não exclui lesão renal aguda.', ['kidneys']],
  ['Gordura cortical felina / variação normal', ['gordura cortical', 'variacao normal felina', 'variacao normal'], 'Deposição lipídica e variações individuais podem modificar os ecos sem disfunção. O significado depende da estrutura e da espécie, não apenas do grau de brilho.', 'Córtex renal felino pode ser relativamente brilhante mesmo com arquitetura preservada; comparar rim e fígado sem considerar isso pode produzir falsa interpretação.', 'Relacionar arquitetura, urina e função renal; evitar classificar como nefropatia apenas pela comparação de ecogenicidade.', ['kidneys']],
  ['Pielonefrite / infecção ascendente', ['pielonefrite', 'infeccao ascendente', 'infeccao/inflamacao'], 'Inflamação/infeção do sistema coletor e interstício pode gerar edema, debris e comprometimento tubular. Obstrução e ectopia podem favorecer ascensão.', 'Pielectasia, ureter visível, debris, alterações corticomedulares e líquido adjacente podem aparecer, ou o exame pode ser discreto/normal.', 'Relacionar sinais sistêmicos, urinálise e cultura quando indicada. Pelve dilatada ou sedimento não confirma pielonefrite sozinho.', ['kidneys', 'ureters']],
  ['Diurese / bexiga distendida / efeito da fluidoterapia', ['diurese', 'fluidoterapia', 'bexiga distendida'], 'Maior produção de urina ou aumento transitório da pressão de saída pode ampliar discretamente o sistema coletor sem lesão obstrutiva fixa.', 'Pequena dilatação pélvica pode ocorrer com parênquima preservado. Deve ser interpretada com ureteres e bexiga, não como hidronefrose automática.', 'Rever fluidos, enchimento vesical, função e evolução; distinguir efeito transitório de obstrução usando o exame completo.', ['kidneys', 'ureters']],
  ['Obstrução urinária / estenose / compressão', ['obstrucao ureteral', 'estenose/ligadura', 'estenose', 'ligadura', 'compressao externa', 'obstrucao cronica'], 'Restrição ao escoamento eleva a pressão proximal. Obstrução persistente pode causar dilatação, reduzir filtração e atrofiar parênquima; a dilatação inicial pode ser pequena.', 'Hidroureter/pielectasia a montante, mudança abrupta de calibre e causa focal podem ser vistos. Na cronicidade pode restar fina camada renal.', 'Determinar lado, causa, função do rim contralateral e repercussão. Obstrução bilateral ou em rim único funcional é especialmente urgente.', ['kidneys', 'ureters']],
  ['Mineralização / calcificação', ['mineralizacao', 'hipercalcemia', 'gastropatia uremica'], 'Mineral pode se depositar em tecido lesionado ou em contexto metabólico. Deposição parenquimatosa difere de cálculo dentro de uma luz.', 'Focos/bandas brilhantes com ou sem sombra dependem da quantidade, tamanho e interfaces. Gás e gordura podem imitar focos brilhantes.', 'Localizar os depósitos e relacionar cálcio, fósforo, função renal e doença do tecido; o aspecto não identifica sozinho o mecanismo metabólico.'],
  ['Doença renal policística', ['doenca policistica', 'policistica heredit'], 'Múltiplos cistos associados a alteração do desenvolvimento/genética aumentam e substituem o parênquima ao longo do tempo.', 'Cavidades anecoicas de tamanhos diferentes, geralmente bilaterais, com reforço posterior; outros órgãos podem ter cistos concomitantes.', 'Relacionar raça/família, bilateralidade e função renal; um cisto isolado não é suficiente para concluir doença hereditária.', ['kidneys']],
  ['Pseudocisto perirrenal / urinoma', ['pseudocisto', 'urinoma', 'urina extravasada'], 'Fluido acumula-se sob/ao redor da cápsula ou fica delimitado após vazamento urinário; não há o revestimento epitelial de um cisto verdadeiro.', 'Coleção circunda parcialmente ou totalmente o rim; o tecido renal pode permanecer separado da cavidade e apresentar alterações crônicas. Ecos não distinguem urina de outros fluidos.', 'Considerar função renal, obstrução, trauma/procedimento e análise do líquido. Não chamar toda coleção perirrenal de urinoma.', ['kidneys', 'ureters']],
  ['PIF e outras doenças infecciosas infiltrativas', ['pif', 'doencas infecciosas', 'criptococ'], 'Inflamação sistêmica/granulomatosa pode infiltrar rim e outros tecidos. No gato, algumas doenças produzem alterações multifocais ou subcapsulares.', 'Aumento renal, nódulos e faixa subcapsular podem ocorrer, mas também aparecem em linfoma e outras condições.', 'Relacionar idade, sinais sistêmicos, efusões e testes dirigidos. A faixa renal não é diagnóstico de PIF.', ['kidneys']],
  ['Gastrite / enteropatia inflamatória / colite', ['gastrite', 'enterite', 'enteropatia inflamatoria', 'colite', 'enteropatia inflamat', 'inflamacao'], 'Edema, infiltrado celular e remodelamento podem ampliar mucosa, submucosa ou muscular. Lesão leve pode preservar interfaces e ser invisível; inflamação intensa pode destruir camadas.', 'Espessamento difuso ou focal, camadas preservadas/alteradas e reação mesentérica são possíveis. Perda de camadas não é exclusividade de tumor.', 'Relacionar segmento, sintomas, albumina, exames dirigidos e histologia quando indicada. No gato, muscular espessada não separa inflamação de linfoma.', ['stomach', 'small-intestine', 'colon']],
  ['Linfangiectasia / enteropatia perdedora de proteínas', ['linfangiectasia', 'perdedora de proteinas'], 'Dilatação de vasos linfáticos intestinais pode permitir perda de linfa e proteínas para o lúmen. Pode ser primária ou secundária a outros processos.', 'Interfaces dos vasos dilatados podem criar estrias mucosas brilhantes. Espessamento, edema e efusões podem coexistir; ausência de estrias não exclui perda proteica.', 'Relacionar albumina, perdas renais/hepáticas, sinais digestivos e amostragem. Estrias ou pontos isolados não medem a perda de proteína.', ['small-intestine']],
  ['Pitiose / infecção gastrointestinal granulomatosa', ['pitiose', 'infeccao granulomatosa', 'granulomas infecciosos'], 'Agente infeccioso desencadeia inflamação profunda, proliferação reativa e fibrose. A parede pode ser substituída por uma massa inflamatória transmural.', 'Espessamento assimétrico com perda de camadas, estenose e linfonodos reativos pode se parecer com neoplasia.', 'Relacionar exposição a ambientes aquáticos/área endêmica, idade e testes específicos. A ultrassonografia não diferencia o agente de outros granulomas/tumores.', ['stomach', 'small-intestine', 'colon']],
  ['Corpo estranho / tricobezoar', ['corpo estranho', 'tricobezoar'], 'Material intraluminal pode impedir passagem, tracionar alças ou lesar a mucosa. A composição e o gás aderido determinam o efeito acústico.', 'Interface brilhante, sombra/reverberação e conteúdo retido proximal podem aparecer; corpo estranho linear produz plicatura e alças reunidas.', 'Ver localização, padrão obstrutivo e lesão mural. Nem todo foco brilhante é corpo estranho; plicatura e sinais de perfuração elevam a urgência.', ['stomach', 'small-intestine']],
  ['Íleo funcional', ['ileo funcional', 'ileo'], 'Motilidade reduzida ocorre por inflamação, distúrbio sistêmico/metabólico ou resposta pós-operatória, sem bloqueio anatômico obrigatório.', 'Distensão e pouco movimento podem envolver vários segmentos, sem transição obstrutiva clara. Uma observação breve pode não capturar contrações normais.', 'Relacionar eletrólitos, medicamentos, cirurgia e órgãos inflamados. Avaliar todo o trajeto para não atribuir a íleo uma obstrução mecânica.', ['stomach', 'small-intestine']],
  ['Obstrução digestiva / estenose', ['obstrucao', 'estenose', 'obstrucao pilorica'], 'Bloqueio anatômico limita o trânsito. Conteúdo se acumula a montante, pressão aumenta e perfusão da parede pode ser comprometida.', 'Mudança de calibre, dilatação proximal, contrações ineficazes e causa focal podem ajudar. A aparência depende da duração e de ser parcial ou completa.', 'Investigar ponto de transição, corpo estranho/massa e perfusão. Distensão isolada não define obstrução; comprometimento agudo requer avaliação rápida.', ['stomach', 'small-intestine', 'colon']],
  ['Hipertrofia pilórica / lesão muscular', ['hipertrofia pilorica', 'hipertrofia', 'leiomioma', 'leiomiossarcoma', 'tumor muscular'], 'Aumento da camada muscular ou massa de origem muscular estreita a luz e modifica o esvaziamento. Hipertrofia e tumor não são processos equivalentes.', 'Camada muscular espessada ou massa focal pode ser relativamente escura, com contrações sem propulsão. Origem na camada e distribuição ajudam, sem determinar histologia.', 'Relacionar idade, conformação, vômitos e efeito obstrutivo. Diferenciar aumento uniforme de massa focal e confirmar a causa conforme indicação.', ['stomach', 'small-intestine', 'colon']],
  ['Úlcera gastrointestinal', ['ulceracao', 'ulcera', 'ulceras'], 'Dano mucoso cria um defeito que pode aprofundar-se até perfurar. Inflamação/edema e gás aderido alteram o entorno.', 'Cratera, foco gasoso na parede, espessamento focal e reação mesentérica podem aparecer; pequenas úlceras podem não ser vistas.', 'Rever medicamentos, doença renal, neoplasia, sangramento e anemia. Sinais de perfuração são urgentes; exame negativo não exclui úlcera.', ['stomach', 'small-intestine']],
  ['Intussuscepção', ['intussuscepcao'], 'Um segmento invagina em outro e carrega mesentério. Compressão venosa gera edema e pode evoluir para isquemia/necrose.', 'Anéis concêntricos no corte transversal e tubos paralelos no longitudinal, frequentemente com gordura no centro; não confundir com lesão em alvo parenquimatosa.', 'Avaliar extensão, obstrução, perfusão e causa precipitante. Dor/comprometimento vascular demandam investigação urgente.', ['small-intestine', 'colon']],
  ['Pancreatite aguda', ['pancreatite aguda', 'pancreatite'], 'Lesão acinar e resposta inflamatória provocam edema do pâncreas e inflamação/lesão da gordura adjacente. O processo pode afetar duodeno e drenagem biliar.', 'Pâncreas aumentado e escuro, gordura ao redor brilhante, líquido e íleo/corrugação duodenal são combinações possíveis. A imagem pode ser normal ou discreta, especialmente em gatos.', 'Relacionar sintomas, lipase pancreática específica e demais órgãos. Achado focal não prova pancreatite; ausência de alteração não a exclui.', ['pancreas', 'gallbladder', 'small-intestine']],
  ['Pancreatite crônica / sequelas', ['pancreatite cronica', 'sequelas'], 'Inflamação persistente ou recorrente pode produzir fibrose, atrofia, alteração ductal e depósitos. A atividade atual nem sempre acompanha a quantidade de remodelamento.', 'Pâncreas irregular, heterogêneo, brilhante ou com mineral/cavidades pode ocorrer; alterações focais podem imitar neoplasia.', 'Relacionar evolução, episódios prévios e testes de função. Morfologia não estima sozinha reserva endócrina/exócrina nem atividade inflamatória.', ['pancreas']],
  ['Pseudocisto pancreático / necrose cavitária', ['pseudocisto', 'necrose cavitaria', 'necrose tumoral'], 'Após lesão, fluido, secreções e tecido necrótico podem ficar delimitados sem o revestimento de um cisto verdadeiro. Tumores também podem cavitar.', 'Cavidade simples ou complexa, com parede/septos, debris e reforço posterior; cisto e pseudocisto podem ser indistinguíveis.', 'Relacionar episódios inflamatórios, evolução e sinais infecciosos; o aspecto não define conteúdo estéril ou origem histológica.', ['pancreas']],
  ['Insulinoma', ['insulinoma'], 'Tumor de células endócrinas pode secretar insulina independentemente das necessidades. Massa pequena pode causar repercussão metabólica importante.', 'Nódulo pancreático pode ser pequeno e pouco conspícuo, sem ecogenicidade exclusiva. Ausência de nódulo não exclui doença funcional.', 'Relacionar hipoglicemia documentada e avaliação hormonal apropriada. Não classificar um nódulo como insulinoma apenas pelo ultrassom.', ['pancreas']],
  ['Insuficiência pancreática exócrina', ['insuficiencia pancreatica exocrina', 'insuficiencia exocrina'], 'Redução da produção/liberação de enzimas compromete digestão. A perda funcional pode existir sem uma alteração estrutural identificável.', 'Pâncreas pode ser pouco visível, menor ou aparentemente normal; janela acústica também limita identificação.', 'Relacionar emagrecimento, fezes e TLI. Tamanho/visibilidade não substitui teste funcional.', ['pancreas']],
  ['Hiperplasia adrenal dependente de estímulo hormonal', ['hiperplasia', 'hipofise', 'hipofisaria', 'hiperadrenocorticismo'], 'Estímulo trófico prolongado pode expandir córtex, inclusive em doença hipofisária. Crescimento não significa que cada aumento seja hormonalmente ativo.', 'Aumento bilateral e arredondamento podem ocorrer, mas glândulas normais ou assimétricas não excluem doença hipofisária.', 'Relacionar sinais, medicamentos e testes endócrinos. Adrenais grandes não confirmam Cushing, e imagem normal não o descarta.', ['adrenals']],
  ['Feocromocitoma', ['feocromocitoma'], 'Tumor da medula adrenal pode secretar catecolaminas e invadir vasos; hemorragia pode complicar a lesão. Atividade hormonal e tamanho não caminham necessariamente juntos.', 'Massa unilateral, heterogênea, com invasão/trombo ou líquido retroperitoneal pode aparecer, sem padrão diagnóstico exclusivo.', 'Relacionar pressão, episódios clínicos e investigação especializada. Planejar coleta/intervenção com avaliação de risco, evitando punção presumida segura.', ['adrenals']],
  ['Adenoma / carcinoma adrenocortical', ['adenoma', 'carcinoma', 'tumor adrenocortical'], 'Proliferação cortical pode ou não secretar hormônios. Invasão local/vascular e necrose aumentam a preocupação, mas nem toda massa é funcional ou maligna.', 'Nódulos ou massas de brilho e textura variáveis, com possível cavitação/mineral. O aspecto não distingue confiavelmente adenoma de carcinoma.', 'Avaliar secreção, lado oposto, vasos e disseminação. No gato hipertenso/hipocalêmico, investigar hiperaldosteronismo sem deduzi-lo apenas da imagem.', ['adrenals']],
  ['Cistite / cistite polipoide', ['cistite', 'cristaluria', 'celulas inflamatorias'], 'Inflamação mucosa provoca edema, infiltração e, por vezes, proliferação polipoide. Pode ser infecciosa ou estéril; cristais não provam infecção.', 'Espessamento mural, projeções, debris e alteração de superfície podem ocorrer. Baixa distensão aumenta espessura aparente e é um confundidor importante.', 'Relacionar sintomas, urinálise e cultura quando indicada. Parede grossa ou sedimento não permite escolher agente/tratamento.', ['bladder']],
  ['Carcinoma urotelial', ['carcinoma urotelial', 'massa urotelial'], 'Proliferação do epitélio urinário pode invadir parede, uretra e desembocaduras ureterais. A extensão provoca obstrução e alterações a montante.', 'Massa mural irregular, às vezes no trígono, com perfusão ou infiltração; pólipos inflamatórios e coágulos podem imitar o aspecto.', 'Ver uretra/ureteres, linfonodos e confirmação especializada. A via de coleta importa pelo risco de implante em trajeto de punção.', ['bladder', 'kidneys', 'ureters']],
  ['Coágulo urinário', ['coagulo'], 'Sangramento gera agregado que pode flutuar ou aderir à parede. Organização cria estrutura sólida sem vasos próprios.', 'Massa móvel ou aderida, geralmente sem sombra e sem perfusão interna detectável. Doppler negativo não comprova que uma lesão seja coágulo.', 'Investigar origem da hematúria e evolução; tumor pode coexistir com coágulo e ser ocultado por ele.', ['bladder', 'kidneys']],
  ['Gás por instrumentação / infecção enfisematosa', ['instrumentacao', 'cistocentese', 'enfisematosa', 'procedimento recente'], 'Instrumentação pode introduzir ar; certos processos infecciosos produzem gás. Ambos geram forte contraste acústico, mas têm significados clínicos distintos.', 'Focos não dependentes, reverberação e sombra suja no lúmen/parede; gás intramural ou persistente pode aumentar preocupação.', 'Rever intervenções recentes e relacionar sintomas/cultura. O artefato mostra gás, não identifica sua origem.', ['bladder', 'gallbladder']],
  ['Hiperplasia prostática benigna / metaplasia', ['hiperplasia prostatica', 'metaplasia'], 'Estímulo hormonal no cão inteiro expande tecido glandular; retenção de secreções pode criar cistos. Metaplasia envolve mudança do epitélio e pode acompanhar estímulo estrogênico.', 'Aumento geralmente simétrico, com pequenos cistos e textura variável. Pode coexistir com infecção, que a imagem não exclui.', 'Considerar idade, castração, exposição hormonal e sinais reprodutivos/urinários. Assimetria importante ou mineral em cão castrado amplia suspeitas.', ['prostate']],
  ['Prostatite', ['prostatite'], 'Inflamação/infeção causa edema e pode evoluir para supuração; cronicidade gera remodelamento fibroso. Hiperplasia/cistos podem predispor.', 'Próstata aumentada, escura ou heterogênea, por vezes com cavidades e reação periférica. Infecção crônica pode ter aspecto brilhante ou menor.', 'Relacionar dor, febre, sintomas urinários e exames dirigidos. A imagem não confirma agente ou esterilidade de cisto.', ['prostate']],
  ['Cisto paraprostático', ['paraprostatico'], 'Cavidade próxima à próstata pode crescer fora do parênquima e conter fluido e septos. O efeito mecânico depende da localização e tamanho.', 'Estrutura extraglandular anecoica/complexa desloca bexiga ou reto; o centro pode parecer líquido simples.', 'Confirmar origem e compressão, correlacionar tenesmo/disúria e investigar infecção se houver contexto.', ['prostate']],
  ['Involução após castração', ['involucao fisiologica', 'involucao', 'atrofia'], 'Redução do estímulo androgênico diminui o volume glandular; atrofia de outras causas também pode reduzir tecido.', 'Próstata menor pode manter arquitetura homogênea; tamanho isolado não distingue involução esperada de doença.', 'Relacionar tempo desde castração, sintomas e demais achados. Ausência de aumento não exclui neoplasia.', ['prostate']],
  ['Piometra / mucometra / hidrometra / hematometra', ['piometra', 'mucometra', 'hidrometra', 'hematometra'], 'O útero retém pus, muco, fluido ou sangue. Na piometra, inflamação/infeção no contexto hormonal pode produzir doença sistêmica; o aspecto do fluido depende das partículas, não do nome da doença.', 'Corpos/cornos dilatados, conteúdo anecoico ou com debris e parede espessada/cística. Pus pode ser pouco ecogênico; muco ou sangue podem ter ecos.', 'Separar os processos pelo ciclo, secreção, exames e estado geral. Conteúdo uterino em paciente doente exige investigar piometra rapidamente.', ['uterus']],
  ['Hiperplasia endometrial cística', ['hiperplasia endometrial'], 'Resposta glandular sob estímulo hormonal cria glândulas dilatadas e mudanças endometriais. Pode favorecer retenção e coexistir com infeção.', 'Pequenos espaços líquidos na parede e espessamento irregular; cavidades dilatadas geram áreas escuras.', 'Relacionar ciclo, hormônios/exposição e sinais sistêmicos. A hiperplasia não é sinônimo de piometra, mas pode fazer parte do mesmo quadro.', ['uterus']],
  ['Gestação / involução puerperal', ['gestacao normal', 'gestacao', 'involucao normal', 'puerperal'], 'Desenvolvimento gestacional modifica parede, conteúdo e vascularização. Após parto, redução do volume e reparação ocorrem ao longo do tempo.', 'Vesículas e conceptos com atividade cardíaca variam conforme estágio; depois do parto pode haver conteúdo e aumento residual.', 'Relacionar datação e evolução seriada. Um exame isolado não determina viabilidade futura nem distingue toda retenção de conteúdo fisiológico.', ['uterus']],
  ['Sofrimento / morte fetal', ['sofrimento fetal', 'hipoxia', 'morte fetal'], 'Comprometimento da oxigenação altera frequência/movimento; morte implica perda da atividade cardíaca no contexto de estágio e exame adequado.', 'Bradicardia relativa ou ausência de batimentos pode ser preocupante. Datação incorreta e limitação técnica precisam ser excluídas.', 'Relacionar frequência materna, estágio e exame repetido adequado; suspeita de sofrimento exige avaliação obstétrica urgente.', ['uterus']],
  ['Coto uterino / granuloma pós-operatório', ['coto', 'reacao e coagulo pos-operatorio', 'pos-operatoratorio'], 'Tecido remanescente, sutura, devitalização, infecção ou hematoma podem formar lesão; exposição hormonal pode sustentar doença de útero remanescente.', 'Massa complexa na região caudal, gordura reativa e líquido podem aparecer; mudanças recentes de cicatrização podem se sobrepor.', 'Relacionar tipo/data de cirurgia, hormônios, febre e persistência. Não diagnosticar piometra de coto apenas por massa adjacente à bexiga.', ['uterus']],
  ['Folículo / corpo lúteo / cisto ovariano', ['foliculo', 'corpo luteo', 'corpos luteos', 'cisto folicular', 'cisto ovariano'], 'Folículos contêm líquido; luteinização transforma estrutura em tecido. Persistência/alteração funcional pode produzir cistos, mas tamanho e fluido não revelam secreção.', 'Cavidades escuras e áreas sólidas relativamente escuras variam com o ciclo. Uma imagem isolada não identifica a fase ou confirma ovulação.', 'Relacionar ciclo, evolução, hormônios e útero. Folículo fisiológico não deve ser classificado automaticamente como cisto patológico.', ['ovaries']],
  ['Tumor ovariano / teratoma', ['tumores ovarianos', 'teratoma', 'lesao cistica neoplasica', 'neoplasia'], 'Proliferação de tecido ovariano pode formar componentes sólidos/císticos e, em alguns tipos, produzir hormônios. Teratoma pode conter tecidos de diferentes composições, inclusive mineral.', 'Massa heterogênea, multiloculada ou com componentes sólidos; focos minerais podem sombrear. O aspecto não determina tipo celular ou atividade hormonal.', 'Relacionar ciclo persistente, útero, líquido e disseminação. Confirmar origem ovariana e natureza por investigação adequada.', ['ovaries']],
  ['Linfadenite / hiperplasia regional', ['infeccao/inflamacao', 'linfadenite', 'linfonodo reativo', 'hiperplasia reativa'], 'Estímulo vindo do território drenado expande populações celulares e pode gerar edema. Infecção profunda pode produzir necrose ou supuração.', 'Aumento, redução de ecos, alteração do hilo e gordura reativa podem ocorrer, com sobreposição a metástase/linfoma.', 'Pesquisar o órgão/tecido drenado e distribuição regional versus generalizada; citologia pode esclarecer quando o resultado muda a conduta.', ['lymph-nodes']],
  ['Ectopia ureteral / ureterocele', ['ectopia', 'ectopico', 'ureterocele'], 'Alteração do desenvolvimento muda o ponto de desembocadura ou cria dilatação terminal. Pode provocar incontinência, retenção e favorecer infecção ascendente.', 'Trajeto líquido além da terminação habitual, dilatação e/ou cavidade na parede vesical podem aparecer. Jatos são intermitentes e sua ausência isolada não confirma ectopia.', 'Relacionar incontinência desde jovem, infecção e rins; exame complementar pode ser necessário para definir trajeto.', ['ureters', 'bladder']],
  ['Jato intermitente / limitação técnica', ['intermitencia', 'limitacao tecnica', 'erro de datacao', 'ajustes'], 'Produção de urina e emissão ureteral variam no tempo. Resolução, janela, duração do exame e configuração de Doppler limitam o que se vê.', 'Ausência de um sinal durante observação breve não equivale a ausência do fenômeno. Ver planos, tempo de observação e estruturas associadas.', 'Usar o conjunto do exame; um achado não visto não deve ser transformado em doença comprovada.'],
  ['Orquite / epididimite', ['orquite', 'epididimite'], 'Inflamação causa edema e infiltração no testículo/epidídimo; hiperemia pode acompanhar fase aguda e fibrose/atrofia a fase crônica.', 'Aumento, áreas escuras, textura mista, fluido escrotal e fluxo aumentado são possíveis.', 'Relacionar dor, febre, reprodução e investigação infecciosa. Heterogeneidade também ocorre com neoplasia/trauma.', ['testes']],
  ['Tumores testiculares', ['seminoma', 'sertoli', 'leydig', 'neoplasia'], 'Proliferação celular distorce túbulos e pode produzir necrose, cavitação ou hormônios, dependendo do tipo.', 'Nódulo/massa e perda do mediastino/arquitetura, com ecos variáveis; não há aspecto exclusivo de seminoma, Sertoli ou Leydig.', 'Considerar testículo retido, assimetria e sinais de feminização/endócrinos; confirmação é celular/tecidual.', ['testes']],
  ['Criptorquidismo', ['criptorquidismo'], 'O testículo não completou a descida e permanece abdominal ou inguinal. A posição altera a localização e pode coexistir com atrofia ou neoplasia.', 'Estrutura com arquitetura/mediastino testicular fora do escroto, por vezes menor e confundível com linfonodo.', 'Confirmar ambos os testículos e investigar massa/torção quando houver aumento ou dor.', ['testes']],
  ['Catarata / esclerose nuclear', ['catarata', 'esclerose nuclear'], 'Alterações das fibras/composição da lente produzem opacidade; compactação nuclear do envelhecimento é um processo distinto da catarata.', 'Catarata pode criar ecos corticais/nucleares e alterar espessura; esclerose pode aparecer como linha fina com núcleo ainda anecoico.', 'Relacionar exame oftálmico, idade, diabetes e inflamação. Ecogenicidade sozinha não determina causa ou estágio funcional da visão.', ['eyes']],
  ['Luxação do cristalino / ruptura', ['luxacao', 'ruptura', 'falha zonular'], 'Falha das zônulas desloca a lente; ruptura da cápsula expõe tecido lenticular e pode provocar inflamação.', 'Posição anterior/posterior ou assimétrica e descontinuidade capsular/tecido adjacente podem aparecer.', 'Relacionar trauma, uveíte, glaucoma e avaliação oftálmica; complicações agudas requerem investigação rápida.', ['eyes']],
  ['Uveíte / inflamação ocular', ['uveite', 'inflamacao', 'edema/trauma corneal'], 'Inflamação altera barreiras e permite entrada de células, proteínas e fluido; pode ser local ou consequência de doença sistêmica.', 'Espessamento uveal/corneal, partículas nas câmaras/vítreo e membranas podem ocorrer; etiologias distintas geram os mesmos ecos.', 'Relacionar exame ocular, pressão e causas sistêmicas dirigidas. O ultrassom não identifica um agente infeccioso.', ['eyes']],
  ['Descolamento de retina', ['hipertensao', 'descolamento', 'trauma'], 'Acúmulo sub-retiniano, tração ou ruptura separa a retina das camadas adjacentes. Hipertensão, inflamação e neoplasia podem alterar permeabilidade ou produzir tração.', 'Membrana refletora ligada ao disco óptico/ora serrata, em V/Y ou com separação parcial; líquido sub-retiniano pode ser escuro ou complexo.', 'Correlacionar visão, pressão arterial e exame oftálmico urgente. Membranas vítreas podem simular descolamento.', ['eyes']],
  ['Degeneração vítrea / hialose asteroide', ['degeneracao', 'hialose', 'remanescentes'], 'Envelhecimento/remodelamento vítreo e partículas lipídico-minerais podem criar refletores; remanescentes embrionários formam estruturas persistentes de outro mecanismo.', 'Pontos brilhantes, pequenas caudas de cometa ou membranas podem aparecer. Inserção e movimento ajudam a distinguir de retina descolada.', 'Relacionar idade e demais estruturas; partículas não significam automaticamente inflamação ou sangue.', ['eyes']],
  ['Hipotireoidismo / tiroidite', ['hipotireoidismo', 'tiroidite'], 'Inflamação e perda de tecido funcional podem levar à atrofia glandular. Estímulo por TSH em outras situações pode produzir aumento, portanto estrutura e função não são equivalentes.', 'Glândula pequena, escura ou heterogênea pode aparecer no cão, sem especificidade suficiente para confirmar o diagnóstico.', 'Relacionar sinais, medicamentos, doença não tireoidiana e painel hormonal; não diagnosticar somente pelo volume.', ['thyroid']],
  ['Hiperplasia / adenoma tireoidiano', ['hiperplasia', 'adenoma', 'adenomatosa'], 'Proliferação folicular expande lóbulos e pode produzir excesso hormonal. Componente cístico e vascularização variam.', 'Lobos/nódulos aumentados, ecos mistos e fluxo aumentado são possíveis, sobretudo em gatos hipertireoidianos.', 'Relacionar T4 e repercussão sistêmica; atividade hormonal e malignidade não são definidas pelo Doppler.', ['thyroid']],
  ['Carcinoma tireoidiano / massa cervical', ['carcinoma', 'massa', 'neoplasia'], 'Crescimento invasivo pode ultrapassar a glândula e afetar vasos/planos adjacentes; outras massas cervicais podem estar próximas.', 'Massa irregular, heterogênea, com possível mineral e extensão regional; lesões bem delimitadas também podem ser neoplásicas.', 'Confirmar origem, extensão e linfonodos. Mobilidade e imagem auxiliam planejamento, mas não substituem confirmação.', ['thyroid']],
  ['Hiperparatireoidismo primário / adenoma / carcinoma', ['adenoma', 'carcinoma', 'hiperplasia'], 'Proliferação de tecido paratireoidiano pode secretar PTH de forma inapropriada para a concentração de cálcio. A imagem apenas localiza/mede tecido, sem medir a secreção.', 'Nódulo escuro junto ou dentro da tireoide pode aparecer; tamanho e aparência se sobrepõem entre adenoma, hiperplasia e carcinoma.', 'Interpretar cálcio ionizado e PTH em conjunto; função renal e outros diferenciais de hipercalcemia fazem parte da investigação.', ['parathyroids']],
  ['Hiperparatireoidismo secundário renal', ['secundario renal'], 'Alterações de fósforo, cálcio e metabolismo da vitamina D na doença renal estimulam cronicamente as glândulas, podendo gerar hiperplasia multiglandular.', 'Mais de uma paratireoide pode aumentar; nem toda hiperplasia é visível e multiplicidade não prova etiologia renal.', 'Relacionar doença renal, fósforo, cálcio e PTH; distinguir resposta secundária de secreção primária inapropriada.', ['parathyroids']],
  ['Vaso / cisto / estrutura não identificada', ['vaso', 'paratireoide normal', 'cisto tireoidiano'], 'Estruturas pequenas com fluido ou sangue podem parecer semelhantes. Resolução e janela determinam se a glândula é visível.', 'Um vaso anecoico acompanha trajeto e pode mostrar Doppler; cisto tem centro líquido. Não ver glândula normal é comum e não exclui doença funcional.', 'Confirmar anatomia e Doppler, relacionando bioquímica antes de classificar o nódulo como paratireoide.', ['parathyroids']],
  ['Doença mixomatosa mitral', ['mixomatosa', 'degenerativa', 'degeneracao valvar'], 'Degeneração dos folhetos/cordas reduz coaptação e produz regurgitação. Sobrecarga crônica de volume pode dilatar átrio e ventrículo; ruptura de corda pode agravar de forma aguda.', 'Folhetos espessados/prolapsados e jato retrógrado no Doppler, com remodelamento das câmaras conforme repercussão.', 'Relacionar sopro, sintomas, tamanho atrial e avaliação cardiológica. Regurgitação não significa automaticamente insuficiência congestiva.', ['heart']],
  ['Endocardite', ['endocardite'], 'Infecção valvar pode formar vegetações, lesar folhetos e produzir insuficiência/embolização. Lesões degenerativas podem imitar parte da imagem.', 'Espessamento irregular ou estruturas móveis na valva e regurgitação são possíveis, sem assinatura que identifique o agente.', 'Relacionar febre, doença sistêmica, culturas e critérios clínicos. Espessamento isolado não comprova endocardite.', ['heart']],
  ['Cardiomiopatia dilatada / disfunção sistólica secundária', ['cardiomiopatia dilatada', 'disfuncao secundaria', 'falencia sistolica'], 'Redução da contratilidade deixa maior volume residual e pode dilatar a câmara. Doença primária, toxicidade, taquicardia, causas nutricionais e sepse podem chegar a um fenótipo parecido.', 'Ventrículo dilatado com movimento reduzido e índices sistólicos baixos; carga, ritmo e técnica interferem nas medidas.', 'Relacionar raça, dieta, medicamentos, arritmia e doença sistêmica. O fenótipo ultrassonográfico não identifica sozinho a causa.', ['heart']],
  ['Cardiomiopatia hipertrófica / hipertrofia secundária', ['cardiomiopatia hipertrofica', 'hipertrofia secundaria', 'hipertireoidismo', 'pseudo-hipertrofia'], 'Aumento de massa miocárdica pode ser primário ou resposta à sobrecarga/hormônios. Menor enchimento também pode aumentar a espessura aparente, sem verdadeira hipertrofia.', 'Paredes espessas, cavidade menor e alterações de enchimento; hipertrofia pode ser regional. Cortes oblíquos e inclusão de estruturas também superestimam a parede.', 'Relacionar pressão, tireoide, hidratação, fase cardíaca e cardiologia. Não aplicar espessura isolada como diagnóstico universal.', ['heart']],
  ['Obstrução dinâmica / SAM', ['obstrucao dinamica'], 'Geometria e fluxo sistólico favorecem movimento anterior da mitral, estreitando temporariamente a via de saída. Intensidade varia com carga e frequência.', 'SAM no modo B/M e aceleração/turbulência no Doppler com possível regurgitação mitral.', 'Distinguir de estenose fixa, relacionar gradiente e contexto do exame; requer avaliação cardiológica integrada.', ['heart']],
  ['Estase atrial / trombose cardíaca', ['estase', 'trombose', 'trombo'], 'Átrio dilatado e contração/fluxo reduzidos favorecem agregação celular e trombo. A presença de contraste espontâneo é um sinal de circulação lenta.', 'Ecos semelhantes a fumaça ou massa intraluminal; o trombo pode não ser visto apesar do risco.', 'Relacionar cardiopatia e sinais embólicos. Dor súbita/paralisia de membros em gato exige atendimento urgente.', ['heart']],
  ['Cardiomiopatia restritiva / disfunção diastólica', ['restritiva', 'disfuncao diastolica'], 'Rigidez miocárdica limita enchimento e aumenta pressão atrial, mesmo com contração ventricular aparentemente preservada.', 'Átrios grandes, ventrículo de dimensões pouco alteradas e possível endocárdio brilhante; Doppler depende de frequência e carga.', 'Interpretar enchimento com morfologia e contexto. Uma relação de ondas isolada não confirma cardiomiopatia restritiva.', ['heart']],
  ['Hipertensão pulmonar / sobrecarga direita', ['hipertensao pulmonar', 'sobrecarga direita'], 'Maior resistência pulmonar aumenta a pressão requerida do ventrículo direito. Sobrecarga de volume por outras cardiopatias também amplia câmaras direitas.', 'Remodelamento direito, alterações septais e Doppler de fluxos/regurgitação podem ajudar a estimar repercussão.', 'Relacionar doenças pulmonares, tromboembolismo e coração. Aumento de câmara não fornece uma pressão pulmonar por si só.', ['heart']],
  ['Efusão pericárdica / tamponamento', ['efusao', 'tamponamento', 'idiopaticas', 'pericardica'], 'Líquido no saco pericárdico eleva a pressão conforme volume, velocidade de acúmulo e complacência. Quando compromete enchimento, pode causar choque obstrutivo.', 'Espaço líquido ao redor do coração; colapso diastólico de câmaras direitas e alterações de enchimento sugerem repercussão hemodinâmica.', 'Relacionar perfusão e estado circulatório. Efusão não é sinônimo de tamponamento; buscar massa e diferenciar líquido pleural.', ['heart']],
  ['Arritmia / cardiomiopatia arritmogênica', ['arritmia', 'arritmogenica'], 'Alteração elétrica pode preceder ou existir sem remodelamento detectável. O ultrassom acompanha movimento, mas não registra toda a atividade elétrica.', 'Exame estrutural pode ser normal; algumas formas evoluem com alterações de câmaras/contratilidade.', 'Relacionar ECG/Holter, síncope, raça e história familiar. Ecocardiograma normal não exclui doença elétrica.', ['heart']],
]);

for (const item of ULTRASOUND_DIFFERENTIAL_EXPLANATIONS) {
  if (item.name === 'Mucocele biliar') item.species = ['dog'];
  if (/felina/i.test(item.name)) item.species = ['cat'];
}

const normalize = (text: string) => text.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLocaleLowerCase('pt-BR');
export function getUltrasoundDifferentialExplanations(organ: UltrasoundOrganId, differentialText: string, species?: UltrasoundSpecies) {
  const text = normalize(differentialText);
  return ULTRASOUND_DIFFERENTIAL_EXPLANATIONS.filter(item => (!item.organs || item.organs.includes(organ)) && (!species || !item.species || item.species.includes(species)) && item.matches.some(alias => text.includes(normalize(alias))));
}
